beforeExample:
public class Example {
    public String extract(String input) {
        return input.substring(1, input.length());
    }
}

afterExample:
public class Example {
    public String extract(String input) {
        return input.substring(1);
    }
}

negativeExample:
public class Example {
    public String extract(String input) {
        return input.substring(1, 3); // end index is not input.length()
    }
}
